using System.Collections.Generic;
using System.Globalization;
using PcbCamStudio.Models;

namespace PcbCamStudio.GCode
{
    public class MarlinWriter : IGCodeWriter
    {
        private static string F(double v) => v.ToString("F3", CultureInfo.InvariantCulture);

        public List<string> WriteHeader(MachineProfile machine)
        {
            return new List<string>
            {
                "; PCB CAM Studio — Marlin 2.0 G-code",
                "; Generated by PCB CAM Studio v1.0",
                "G21        ; mm units",
                "G90        ; absolute positioning",
                "G92 X0 Y0 Z0  ; set current position as zero",
                $"M3 S{machine.SpindleSpeed}  ; spindle on",
                "G4 P2000   ; wait 2s for spindle to spin up",
                $"G0 Z{F(2.0)}   ; lift to safe height"
            };
        }

        public List<string> WriteFooter(MachineProfile machine)
        {
            return new List<string>
            {
                "M400       ; wait for moves to finish",
                "M5         ; spindle off",
                "G0 Z5.000  ; raise Z",
                "G0 X0 Y0   ; return to origin",
                "; Job complete"
            };
        }

        public List<string> WriteIsolation(Toolpath toolpath, MachineProfile machine)
        {
            var lines = new List<string>();
            lines.Add($"; --- {toolpath.Label} ---");

            foreach (var move in toolpath.Moves)
            {
                if (move.IsRapid)
                    lines.Add($"G0 X{F(move.Position.X)} Y{F(move.Position.Y)} Z{F(move.Z)}");
                else
                    lines.Add($"G1 X{F(move.Position.X)} Y{F(move.Position.Y)} Z{F(move.Z)} F{machine.CutFeed}");
            }

            return lines;
        }

        public List<string> WriteDrilling(Toolpath toolpath, MachineProfile machine)
        {
            var lines = new List<string>();
            lines.Add($"; --- {toolpath.Label} ---");
            lines.Add($"M0 ; Insert drill bit Ø{toolpath.ToolDiameter:F2}mm then press Resume");

            foreach (var move in toolpath.Moves)
            {
                if (move.IsRapid)
                    lines.Add($"G0 X{F(move.Position.X)} Y{F(move.Position.Y)} Z{F(move.Z)}");
                else
                    lines.Add($"G1 Z{F(move.Z)} F{machine.DrillFeed}");
            }

            return lines;
        }

        public List<string> WriteCutout(Toolpath toolpath, MachineProfile machine)
        {
            var lines = new List<string>();
            lines.Add($"; --- {toolpath.Label} ---");
            lines.Add("M0 ; Insert cutout bit then press Resume");

            foreach (var move in toolpath.Moves)
            {
                if (move.IsRapid)
                    lines.Add($"G0 X{F(move.Position.X)} Y{F(move.Position.Y)} Z{F(move.Z)}");
                else
                    lines.Add($"G1 X{F(move.Position.X)} Y{F(move.Position.Y)} Z{F(move.Z)} F{machine.CutFeed}");
            }

            return lines;
        }
    }
}
